PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT ?s ?title ?status WHERE {
  ?s rdfs:label ?title .
  FILTER(CONTAINS(STR(?s), "/Constraint/"))
  OPTIONAL { ?s <https://trivyn.io/ontologies/moose#hasLifecycleStatus> ?status }
}
ORDER BY ?title

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT ?s ?title ?status WHERE {
  ?s rdfs:label ?title .
  FILTER(CONTAINS(STR(?s), "/Constraint/"))
